using FluentValidation;
namespace OAS.Application.Accounting.ReceiptVouchers.Commands.UpdateReceiptVoucher;
public sealed class UpdateReceiptVoucherCommandValidator:AbstractValidator<UpdateReceiptVoucherCommand>{public UpdateReceiptVoucherCommandValidator(){RuleFor(x=>x.Id).NotEmpty();RuleFor(x=>x.Data.RowVersion).NotEmpty();RuleFor(x=>x.Data.Lines).NotEmpty().WithErrorCode("receipt_voucher_lines_required");RuleForEach(x=>x.Data.Lines).ChildRules(l=>{l.RuleFor(x=>x.CurrencyId).NotEmpty();l.RuleFor(x=>x.Amount).GreaterThan(0);l.RuleFor(x=>x.ExchangeRate).GreaterThan(0).When(x=>x.ExchangeRate.HasValue);});}}
